import pytest


def parity(x: int) -> bool:
    """True when the byte x (an int from 0 to 255) has an odd number of set bits."""
    return bin(x).count("1") % 2 == 1


def test_parity_zero_is_even() -> None:
    assert parity(0) is False


def test_parity_single_bit_is_odd() -> None:
    assert parity(1) is True
    assert parity(128) is True


def test_parity_two_bits_is_even() -> None:
    assert parity(3) is False
    assert parity(129) is False


def test_parity_three_bits_is_odd() -> None:
    assert parity(7) is True


def test_parity_all_bits_set_is_even() -> None:
    assert parity(255) is False


@pytest.mark.parametrize("x", range(256))
def test_parity_returns_bool(x: int) -> None:
    assert isinstance(parity(x), bool)
